lookup={r[0]:r for r in sources['Verbos']}
available=[]
for w in preferred:
    if w in lookup and w not in available:available.append(w)
# Sample across the curated action list to retain a broad alphabet and range of actions.
assert len(available)>=200,len(available)
verbs=[lookup[available[(i*len(available))//200]] for i in range(200)]
verbs.sort(key=lambda r:norm(r[0]))
cats=collections.defaultdict(list)
for row in sources['Variado']:cats[row[1]].append(row)
# Ten entries from every category, spread through the original pack.
var=[]
positions=[0,2,5,10,15,20,25,30,35,45]
for pos in positions:
    for rows in cats.values():var.append(rows[pos])
var=[[('dron' if w=='drone' else w),c] for w,c in var]
